<?php
require __DIR__.'/config.php';require_login();$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$st=$pdo->prepare("SELECT COUNT(*) receipts,COALESCE(SUM(total),0) sales,COALESCE(SUM(amount_paid),0) collected,COALESCE(SUM(CASE WHEN status='utang' THEN total-amount_paid ELSE 0 END),0) debt FROM sales WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'void'");$st->execute([$from,$to]);$totals=$st->fetch();$st=$pdo->prepare("SELECT COALESCE(SUM(si.quantity*(si.unit_price-si.unit_cost)),0) profit FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE DATE(s.created_at) BETWEEN ? AND ? AND s.status<>'void'");$st->execute([$from,$to]);$profit=(float)$st->fetchColumn();$st=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date BETWEEN ? AND ?');$st->execute([$from,$to]);$expense=(float)$st->fetchColumn();$st=$pdo->prepare("SELECT s.*,COALESCE(c.name,'Walk-in') customer,u.name cashier FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.user_id WHERE DATE(s.created_at) BETWEEN ? AND ? AND s.status<>'void' ORDER BY s.created_at DESC");$st->execute([$from,$to]);$rows=$st->fetchAll();$daily=$pdo->prepare("SELECT DATE(created_at) day,SUM(total) total,COUNT(*) receipts FROM sales WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'void' GROUP BY DATE(created_at) ORDER BY day DESC");$daily->execute([$from,$to]);$dailyRows=$daily->fetchAll();$pageTitle='Reports';require __DIR__.'/partials/header.php';?>
<div class="page-intro"><div><h1>Sales & Business Reports</h1><p>Review store performance for your selected date range.</p></div><button class="btn secondary" onclick="window.print()">Print report</button></div><section class="panel"><form class="filter-bar"><div><label>From date</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To date</label><input type="date" name="to" value="<?=e($to)?>"></div><button class="btn primary">Run report</button><a class="btn secondary" href="reports.php">This month</a></form></section><div class="stats-grid report-stats"><article class="stat-card"><span class="muted">Gross sales</span><strong><?=money($totals['sales'])?></strong><small><?=e($totals['receipts'])?> transactions</small></article><article class="stat-card"><span class="muted">Estimated gross profit</span><strong><?=money($profit)?></strong><small>Sales less recorded product cost</small></article><article class="stat-card"><span class="muted">Expenses</span><strong><?=money($expense)?></strong><small>Operating expenses recorded</small></article><article class="stat-card"><span class="muted">Utang balance</span><strong><?=money($totals['debt'])?></strong><small>Outstanding for this period</small></article></div><section class="panel section-gap"><div class="panel-heading"><div><h2>Daily sales summary</h2><p><?=e($from)?> through <?=e($to)?></p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Receipts</th><th>Sales</th></tr></thead><tbody><?php if(!$dailyRows):?><tr><td colspan="3" class="empty">No sales for this period.</td></tr><?php endif;foreach($dailyRows as $d):?><tr><td><?=e($d['day'])?></td><td><?=e($d['receipts'])?></td><td><?=money($d['total'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel section-gap"><div class="panel-heading"><div><h2>Transaction history</h2><p>Detailed sales records</p></div><button class="btn secondary compact" onclick="window.print()">Print / Save PDF</button></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Date</th><th>Customer</th><th>Cashier</th><th>Payment</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">No transactions found.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['receipt_no'])?></td><td><?=e($r['created_at'])?></td><td><?=e($r['customer'])?></td><td><?=e($r['cashier']??'—')?></td><td><?=e(strtoupper($r['payment_method']))?></td><td><span class="pill <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><?=money($r['total'])?></td><td><a href="receipt.php?id=<?=$r['id']?>">Receipt</a></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel section-gap"><div class="panel-heading"><div><h2>Business summary</h2><p>Estimated figures for the selected period</p></div></div><div class="summary-grid"><div><span>Sales</span><b><?=money($totals['sales'])?></b></div><div><span>Gross profit</span><b><?=money($profit)?></b></div><div><span>Expenses</span><b><?=money($expense)?></b></div><div><span>Profit after expenses (estimate)</span><b><?=money($profit-$expense)?></b></div><div><span>Cash / other collected</span><b><?=money($totals['collected'])?></b></div></div><p class="hint">Gross profit uses the product unit cost saved at the time of sale. This report is an operational estimate, not a substitute for formal accounting.</p></section><?php require __DIR__.'/partials/footer.php';?>